data.query:
query Query($where: ProductionSetupOutputWhereInput!, $orderBy: [ProductionSetupOutputOrderByInput!], $first: Int, $after: String, $whereP:InventoryWhereInput, $wherePH: ProductionHistoryWhereInput) {
  output:productionSetupOutput(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        producedQuantity
        scrappedQuantity
        unitPerCycle
        standardPackQuantity
        remainingBalance
        virtual
        product {
          id
          customData
        }
        productionSetup {
          id
          productionRuns(first:1,where: {active: {_eq:true}}){edges{node{id}}}
          mode {
            id 
            modeType {
              production
              changeover
            }
          }
          eventId
          operators(
          where: {
            operatorActivity: {
              includeLabor: {
                _eq:true      
              }
            }
          }
        ) {
            total
            edges {
              node {
                laborWeight
                employeeId
              }
            }
          }
        }
        workcenter {
          code
          id
          name
          shiftGroupId
          locationId
        }

        dist:workOrderDistribution {
          id
          setupOperators
          productionOperators
          standardRate
          actualStartAt
          standardPackQuantity
          distributionGroup {
            id

            requireParallelOutput
            workOrderProcessDistributionStatusId
            parallelPositions
            distributions{total}
          }

          leadingDistribution {
            id
            output:productionSetupOutputs {
              edges {
                node {
                  id

                  boms:setupBoms(where:{
                    consumptionMode: {
                      noConsumption: {
                        _eq: false
                      }
                    }, bomTypeId: {
                      _eq: "Product"
                    }
                  }) {
                    edges {
                      node {
                        standardUsage
                        minimumUsage
                        maximumUsage
                        componentProductStrategyProcessId
                        componentProduct {id code}
                        componentPackagingMaterialId
                        componentProductStrategyId
                        bomTypeId
                        workOrderProcessId
                        consumptionMode {
                          intraprocess
                          noConsumption
                          transferSerial
                          requireSerial
                          standardUsage
                          validateOnProduction
                          actualUsage
                        }
                      }
                    }
                  }
                }
              }
            }
          }
          balanceQuantity
          standardRate
          laborUsage
          machineUsage
          materialUsage
          producedQuantity
          requiredQuantity
          scrappedQuantity
          setupRate
          leadingProduct
          workOrderProcessDistributionStatusId
          workOrder {
            id 
            workOrderProcesses {
              edges {
                node {
                  id 
                  order
                  final
                }
              }
            }
          }
          workOrderProcess {
            id
            code
            final
            productStrategy {
              id
              productId
              inventoryUnitId
            }
            wip
            finishedGood
            transferSerial
            unitWeight
            weightUnitId
            lotControl {
              beginProcessId
              autoLotNumber
            }
            productStrategyProcessId
            productStrategyProcess{
              qualitySubjectLists {
                edges {
                  node {
                      id
                      interval {
                        id
                    }
                }
              }
            }
            }
            productionType{
              id
              byProduct
              cell
              disassembly

              outside
              packaging
              production


              rework
            }
          }
          productionHistories(where:$wherePH, orderBy: {field: occurAt, direction:desc}, first:1) {
            edges {
              node {
                occurAt
              }
            }
          }

        }
        standardBoms:setupBoms(where: {
          _and:[{
            consumptionMode: {
              transferSerial: {
                _eq:false
              }
            }
          }
        ]}) {

          edges {
            node {
              standardUsage
              minimumUsage
              maximumUsage
              componentProductStrategyProcessId
              componentProduct {id code}
              componentPackagingMaterialId
              componentProductStrategyId
              bomTypeId
              standardPackQuantity
              workOrderProcessId
              consumptionMode {
                intraprocess
                transferSerial
                standardUsage
                validateOnProduction
                requireSerial
                noConsumption
                actualUsage
              }

            }
          }
        }
        serialBoms:setupBoms(where: {
          _or:[{
            consumptionMode: {
              transferSerial: {
                _eq:true
              }
            }
          }
        ]}) {

          edges {
            node {
              standardUsage
              componentProductStrategyProcessId
              componentProduct{id code}
              componentPackagingMaterialId
              componentProductStrategyId
              bomTypeId
              standardPackQuantity
              workOrderProcessId
              consumptionMode {
                intraprocess
                transferSerial
                standardUsage
                validateOnProduction
                requireSerial
                noConsumption
                actualUsage
              }

            }
          }
        }
        updatedAt
      }
    }
  }
  partial:inventory(where:$whereP){
    edges {
      node {
        id
        grossWeight
        netWeight
        tareWeight
        theoreticalWeight
        active
        quantity {
          value
          unitId
        }
        inventoryStatusId
        inventoryTypeId
        locationId
        lotId
        masterInventoryId
        packagingMaterialId
        productId
        productStrategyProcessId
        weightUnitId
        workOrderId
        workOrderProcessId
      }
    }
}
}

