data.transform:
function buildTrx(material, output, serials, partials) {
    const inventory = {};
    for (let i = 0; i < material.length; i++) {
        const m = material[i];
        if (m.inventory.quantity.value === m.originalQuantity) continue;
        inventory[m.inventory.id] = {
            ...m.inventory,
            originalQuantity: m.originalQuantity,
            materialId: m.id
        }
    }
    const production = [];
    if (serials.length) {
        for (let i = 0; i < output.length; i++) {
            const serial = serials.shift();
            const o = output[i];
            production.push({
                serial: serial.inventory,
                partial: null,
                quantity: o.qty,
                trx: o.inv.map(inv => ({
                    inventory: { ...inventory[inv.id], quantity: { value: inv.qty, unitId: inventory[inv.id].quantity.unitId } }

                })
                )
            })

        }

    }
    else {
        for (let i = 0; i < output.length; i++) {
            const o = output[i];

            production.push({
                serial: null,
                partial: o.partial && partials?.length ? partials.find(p => p.id === o.partial.id) : null,
                quantity: o.qty,
                trx: o.inv.map(inv => ({

                    inventory: { ...inventory[inv.id], quantity: { value: inv.qty, unitId: inventory[inv.id].quantity.unitId } }
                })
                )
            })

        }
    }
    return { inventory, production }
}

const { inventory, production } = buildTrx($.material, $.output, $state.context.REQUEST.DATA?.productionTypeId === 'Production (Transfer Serial)' ? [...$state.context.LOCAL.serialMaterial] : [], $state.context.LOCAL?.partial?.length > 0 ? [...$state.context.LOCAL.partial] : []);
return {inventory, production}

(
  $L := $state.context.LOCAL;
  $wop := $L.dist.workOrderProcess;
  $psp := $L.output.card.rack.productStrategyProcess;
  $R := $state.context.REQUEST;
  $D := $R.DATA;
  $outputQty := $sum(production.quantity);
  $ts :=
    (
      $L.dist.workOrderProcess.transferSerial
        or
      $L.card.rack.productStrategyProcess.transferSerial
    );

  $createInventory := $ts ? [] : [production[$isNilOrEmpty(partial) and $isNilOrEmpty(serial)].{
    "create": {
      "grossWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * quantity,  /*plus packaging? */
      "netWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * quantity,
      "tareWeight": 0, /* packaging * quantity???? $coalesce([$wop.unitWeight,0]) * quantity, */
      "theoreticalWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * quantity, /*=gross??*/
      "active": $R.OCustomer-DON.scrap ? false : true,
      /* "barcode":"", */
      /* "externalId":"", */
      /* "note":"", */
      /* "trackingNumber":"", */
      "customData": $D.customData,
      "quantity": {
        "value": quantity,
        "unitId": $coalesce([$wop.productStrategy.inventoryUnitId,$psp.productStrategy.inventoryUnitId])
      },
      "inventoryStatusId": $R.OCustomer-DON.scrap ? "Scrap" : $isNilOrEmpty($wop.productStrategyProcess.qualitySubjectLists.edges.node.id) ? "OK" : "QC (Hold)",
      "inventoryTypeId": $wop.finishedGood or  $psp.finishedGood ? "Finished Goods" : "WIP",
      "locationId": $L.output.workcenter.locationId,
      /* "lotId":"",  */
      "masterInventoryId": $D.masterInventoryId,
      /* "packagingMaterialId": "",  packaging bom etc*/
      "productId": $coalesce([$wop.productStrategy.productId,$psp.productStrategy.productId]),
      "productStrategyProcessId": $coalesce([$wop.productStrategyProcessId,$psp.id]),
      "weightUnitId": $coalesce([$wop.weightUnitId,$psp.weightUnitId]),
      "workOrderId":$L.dist.workOrder.id,
      "workOrderProcessId": $wop.id,
      "kanbanCardId": $L.output.card.id
    }
  }];

  $updateSerial := $ts ? [] : [production[$not($isNilOrEmpty(serial))].serial.{
    "update": {
      "grossWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity,  /*plus packaging? */
      "netWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity,
      "tareWeight": 0, /* packaging * quantity???? $coalesce([$wop.unitWeight,0]) * quantity, */
      "theoreticalWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity, /*=gross??*/
      "active": $R.OCustomer-DON.scrap ? false : true,
      "inventoryStatusId": $R.OCustomer-DON.scrap ? "Scrap" : $isNilOrEmpty($wop.productStrategyProcess.qualitySubjectLists.edges.node.id) ? "OK" : "QC (Hold)",
      "inventoryTypeId": $wop.finishedGood or  $psp.finishedGood ? "Finished Goods" : "WIP",
      "locationId": $L.output.workcenter.locationId,
      "masterInventoryId": $coalesce([$D.masterInventoryId,masterInventoryId]),
      /* "packagingMaterialId": "", */
      "productId": $coalesce([$wop.productStrategy.productId,$psp.productStrategy.productId]),
      "productStrategyProcessId": $coalesce([$wop.productStrategyProcessId,$psp.id]),
      "weightUnitId": $coalesce([$wop.weightUnitId,$psp.weightUnitId]),
      "workOrderProcessId": $wop.id,
      "kanbanCardId": $L.output.card.id
    }, "where": {
      "id":id    
    }
  }];
  $updatePartial :=  $ts ? [] : [production[$not($isNilOrEmpty(partial))].partial.{
    "update": {
      "grossWeight": $coalesce([grossWeight,0]) +$coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity,  /*plus packaging? */
      "netWeight": $coalesce([netWeight,0]) +$coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity,  
      "tareWeight": 0, /* packaging * quantity???? $coalesce([$wop.unitWeight,0]) * quantity, */
      "theoreticalWeight":  $coalesce([theoreticalWeight,0]) +$coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity, /*=gross??*/
      /* NO SCRAP ON UPDATES TO PARTIALS -- you would create scrap separately */
      "active": true,
      "quantity": {
        "value": quantity.value + %.quantity,
        "unitId": quantity.unitId
      },
      "inventoryStatusId": %.quantity + quantity.value = $L.standardPack ? ($isNilOrEmpty($wop.productStrategyProcess.qualitySubjectLists.edges.node.id) ? "OK" : "QC (Hold)") : "Pending Production"    
    }, "where": {
      "id":id    
    }
  }];

  $updateOutput := [$L.output.{
    "update": {
      "producedQuantity": $R.OCustomer-DON.scrap ? producedQuantity : producedQuantity + $outputQty,
      "scrappedQuantity": $R.OCustomer-DON.scrap ? scrappedQuantity + $outputQty : scrappedQuantity,
      "remainingBalance": $R.OCustomer-DON.scrap ? remainingBalance : remainingBalance - $outputQty
    }, "where": {
      "id": id
    }
  }];
    $updateCmp := [$each(inventory, function($v, $k) {
    {
      "update": {
        "quantity": $v.quantity,
        "active": $v.quantity.value > 0
      }, "where": {
        "id":$k
      }
    }
  })];


  {
    "payloadC": $createInventory,
    "payloadU": $append($updatePartial,$updateSerial),
    "payloadO": $updateOutput,
    "payloadCI": $updateCmp
  }

)

{
  "LOCAL": {
    "production": $
  }
}

{
  "LOCAL": $
}

{
  "SUCCESS": true,
  "MESSAGE": "Produced "
    & $state.context.REQUEST.DATA.quantity
    & " units "
    & $coalesce([
      $state.context.LOCAL.dist.workOrderProcess.code,
      $state.context.LOCAL.output.card.rack.productStrategyProcess.code
    ])
}

data.query:
query Query($pi:InventoryWhereInput, $ph: ProductionHistoryWhereInput, $ps: ProductionSetupWhereInput) {
  partial:inventory(where:$pi){
    edges {
      node {
        id
        grossWeight
        netWeight
        tareWeight
        theoreticalWeight
        active
        quantity {
          value
          unitId
        }
        inventoryStatusId
        inventoryTypeId
        locationId
        lotId
        masterInventoryId
        packagingMaterialId
